mapper.update:
UPDATE item
title = #{title}, category_id = #{categoryId}, price = #{price}, original_price = #{originalPrice}, condition_level = #{conditionLevel}, cover = #{cover}, description = #{description}, campus_area = #{campusArea}, status = #{status}, audit_remark = #{auditRemark}, update_time = NOW(), update_user = #{updateUser},
WHERE id = #{id}

mapper.select:
SELECT i.*, m.nickname AS sellerNickname, m.avatar AS sellerAvatar, c.name AS categoryName
FROM item i
LEFT JOIN member m ON i.seller_id = m.id
LEFT JOIN category c ON i.category_id = c.id

    AND i.status = #{status}
    AND i.seller_id = #{sellerId}
    AND i.category_id = #{categoryId}
    AND i.campus_area = #{campusArea}

        AND (i.title LIKE CONCAT('%', #{keyword}, '%') OR i.description LIKE CONCAT('%', #{keyword}, '%'))



    ORDER BY i.price ASC
    ORDER BY i.price DESC
    ORDER BY i.want_count DESC, i.create_time DESC
    ORDER BY i.create_time DESC
